def report(i):
 old=m.idea_sources; m.idea_sources=sources
 try: t=m.report(i)
 finally: m.idea_sources=old
 raw="Short" if i["raw_short"] else "Long"; generic="회계이익에서 운전자본·담보·규제자본·maintenance/growth investment·interest·tax를 차감하고, common보다 선순위인 계약·채권자 청구권을 먼저 배치한다. 자산가치와 계약상 수취액은 현금화 날짜·세금·재투자 의무를 반영한다. 기업가치가 맞아도 security와 duration이 틀리면 투자결과는 실패할 수 있다."
 t=t.replace("Batch 046 canonical report.","Batch 051 canonical report.").replace("### Common equity cash waterfall","### Security cash waterfall").replace(generic,i["waterfall"])
 t=t.replace("이번 10건은 첨부 SQL에 performance row가 없으므로 1개월~5년 수익률을 만들지 않는다. 사건 성공, 기업 생존, target 도달과 투자 total return을 각각 별도 필드로 둔다. corporate action이 있으면 successor security까지 연결돼야 정확한 IRR을 계산할 수 있다.","첨부·repository에 정확한 performance row가 없다. 기업·사건 결과와 security total return을 분리하며 배당·청산분배·successor shares를 날짜별로 복원하기 전 return과 IRR은 null이다.")
 t=t.replace(f"`ATH`를 회사로 보지 말고 {i['entity']} 법인·exchange·날짜로 고정한다.",f"`{i['ticker']}`와 날짜를 {i['entity']}의 실제 법인·security에 고정한다.")
 t=t.replace(f"| 회사 / 원 ticker | {i['entity']} / {i['ticker']} |",f"| 회사 / 원 ticker | {i['entity']} / {i['ticker']} |\n| 실제 Security | **{i['security']}** |")
 return t

